// Seeded pseudo-random for stable per-stroke effects (chalk noise, glitter positions).
const _pr = (seed) => { const x = Math.sin(seed + 1) * 10000; return x - Math.floor(x); };

// Returns Konva.Line constructor props for the live draw preview layer.
function getBrushDrawProps(brushId, color, size) {
  switch (brushId) {
    case "marker":      return { stroke: color, strokeWidth: size * 2,   lineCap: "butt",   lineJoin: "round", opacity: 0.6,  tension: 0.3 };
    case "highlighter": return { stroke: color, strokeWidth: size * 4,   lineCap: "square", lineJoin: "miter", opacity: 0.25, tension: 0.3 };
    case "finetip":     return { stroke: color, strokeWidth: size * 0.4, lineCap: "round",  lineJoin: "round", opacity: 1,    tension: 0   };
    case "brush":       return { stroke: color, strokeWidth: size * 1.5, lineCap: "round",  lineJoin: "round", opacity: 0.85, tension: 0.5 };
    case "dotted":      return { stroke: color, strokeWidth: size,       lineCap: "round",  lineJoin: "round", opacity: 0.9,  tension: 0,   dash: [size, size * 3] };
    case "chalk":       return { stroke: color, strokeWidth: size * 1.5, lineCap: "round",  lineJoin: "round", opacity: 0.55, tension: 0.3 };
    case "neon":        return { stroke: color, strokeWidth: size * 3,   lineCap: "round",  lineJoin: "round", opacity: 0.5,  tension: 0.5, shadowColor: color, shadowBlur: 15, shadowEnabled: true };
    case "glitter":     return { stroke: color, strokeWidth: size * 0.5, lineCap: "round",  lineJoin: "round", opacity: 0.5,  tension: 0,   dash: [2, 10] };
    default:            return { stroke: color, strokeWidth: size,       lineCap: "round",  lineJoin: "round", opacity: 1,    tension: 0.5 };
  }
}

