const rand = (a, b) => a + Math.random() * (b - a);
const uid = () => (typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).slice(2, 9));

// Module-level image cache so loaded images persist across re-renders
const _imgCache = {};
const _imgErrorCache = new Set();
// Returns { img, error } where img is a loaded HTMLImageElement or null while loading.
// All images are fetched with crossOrigin="anonymous" so the browser cache stores a
// CORS-enabled copy, which Konva can read without tainting the canvas.
function useKonvaImage(src) {
  const [state, setState] = useState(() => ({
    img: _imgCache[src] || null,
    error: _imgErrorCache.has(src),
  }));
  useEffect(() => {
    if (!src || _imgCache[src] || _imgErrorCache.has(src)) return;
    const el = new window.Image();
    el.crossOrigin = "anonymous";
    el.onload = () => {
      _imgCache[src] = el;
      setState({ img: el, error: false });
    };
    el.onerror = () => {
      _imgErrorCache.add(src);
      setState({ img: null, error: true });
    };
    el.src = src;
  }, [src]);
  return state;
}

const todayDate = () => {
  const d = new Date();
  return `${String(d.getMonth()+1).padStart(2,"0")}.${String(d.getDate()).padStart(2,"0")}.${String(d.getFullYear()).slice(2)}`;
};
const nowTime = () => new Date().toLocaleTimeString([], {hour: 'numeric', minute: '2-digit'});

// ============================================================
// COVER PHOTO LOGIC
// ============================================================
function getCoverPhoto(entry) {
  if (entry.coverPhoto) return { type: "image", src: entry.coverPhoto };
  // Auto-pick an image from the entry
  if (entry.type === "photo") return { type: "image", src: entry.image };
  if (entry.type === "collage") {
    const firstImg = entry.items?.find(i => i.type === "image");
    if (firstImg) return { type: "image", src: firstImg.src };
  }
  if (entry.type === "journal") {
    if (entry.images?.length > 0) return { type: "image", src: entry.images[0] };
  }
  if (entry.type === "checkin" && entry.images?.length > 0) {
    return { type: "image", src: entry.images[0] };
  }
  // Fallback: generated "check-in / journal / collage" cover
  return { type: "generated", entryType: entry.type, date: entry.date };
}

// ============================================================
// MAIN APP
// ============================================================
export default function App({ session }) {
  const [view, setView] = useState("feed");
  const [compose, setCompose] = useState(null); // null | "photo" | "collage-new" | "journal-new" | "checkin-new"
  const [openEntry, setOpenEntry] = useState(null);
  const [editingScrapbookEntry, setEditingScrapbookEntry] = useState(null);
  const [filter, setFilter] = useState("all");

  const userId = session?.user?.id;

  const [entries, setEntries] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(null);

  useEffect(() => {
    if (!userId) return;
    let cancelled = false;
    (async () => {
      try {
        const rows = await fetchEntries(userId);
        if (!cancelled) { setEntries(rows); setLoadError(null); }
      } catch (err) {
        console.error("fetch entries failed", err);
        if (!cancelled) setLoadError(err?.message || "failed to load your journal");
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [userId]);

  const addEntry = (entry) => {
    const full = { ...entry, id: entry.id || uid() };
    setEntries(prev => [full, ...prev]);
    setCompose(null);
    upsertEntry(full, userId).catch(err => console.error("save failed", err));
    return full;
  };
  const entriesRef = useRef(entries);
  entriesRef.current = entries;
  const updateEntry = (id, patch) => {
    const existing = entriesRef.current.find(e => e.id === id);
    if (!existing) return;
    const merged = { ...existing, ...patch };
    setEntries(prev => prev.map(e => e.id === id ? merged : e));
    upsertEntry(merged, userId).catch(err => console.error("save failed", err));
  };
  const deleteEntry = (id) => {
    setEntries(prev => prev.filter(e => e.id !== id));
    setOpenEntry(null);
    setEditingScrapbookEntry(null);
    deleteEntryById(id).catch(err => console.error("delete failed", err));
  };

  const handleSignOut = async () => { await signOut(); };

  // All photos available to scrapbook = photo entries + images in other entries
  const photoImages = useMemo(() => {
    const out = [];
    for (const e of entries) {
      if (e.type === "photo") out.push(e.image);
      if (e.type === "collage") for (const it of (e.items || [])) if (it.type === "image") out.push(it.src);
      if (e.type === "journal" || e.type === "checkin") for (const img of (e.images || [])) out.push(img);
    }
    return [...new Set(out)];
  }, [entries]);

  // Scrapbook shows all non-photo entries
  const scrapbookEntries = entries.filter(e => e.type !== "photo");

  return (
    <div className="min-h-screen w-full relative overflow-hidden"
      style={{ background: "linear-gradient(160deg, #f7d6ff 0%, #c5b3ff 25%, #ffb4de 55%, #a7e6ff 100%)", fontFamily: "'Space Grotesk', sans-serif" }}>
      <GlobalStyles />
      <AmbientBackground />
      <FloatingSparkles />

      <button onClick={handleSignOut} title="sign out"
        className="fixed top-4 right-4 z-20 w-9 h-9 rounded-full glass-light flex items-center justify-center transition hover:scale-110">
        <LogOut className="w-4 h-4" style={{color: "#3d1d6b"}} />
      </button>

      {loading && (
        <div className="absolute top-4 left-4 z-20 px-3 py-1.5 rounded-full glass-light italic"
          style={{color: "#5b3a8a", fontFamily: "'Caveat', cursive", fontSize: 16}}>
          ✦ loading your journal ✦
        </div>
      )}
      {loadError && (
        <div className="absolute top-4 left-4 z-20 px-3 py-1.5 rounded-full italic"
          style={{background: "rgba(255,200,200,0.8)", color: "#8a1b3a", fontSize: 12}}>
          {loadError}
        </div>
      )}

      <div className="relative z-10 max-w-xl md:max-w-6xl mx-auto pb-36">
        <Header />
        {loading ? (
          <div className="flex items-center justify-center py-24">
            <p className="italic" style={{color: "#7a5aa8", fontFamily: "'Caveat', cursive", fontSize: "20px"}}>
              ✦ loading your journal ✦
            </p>
          </div>
        ) : loadError ? (
          <div className="text-center py-24 px-6">
            <p className="italic text-sm" style={{color: "#8a1b3a"}}>{loadError}</p>
          </div>
        ) : view === "feed" ? (
          <FeedView entries={entries} onOpen={setOpenEntry} filter={filter} setFilter={setFilter} />
        ) : (
          <ScrapbookView
            entries={scrapbookEntries}
            onOpen={(e) => setEditingScrapbookEntry(e)}
            onDelete={(e) => deleteEntry(e.id)}
            onNewCompose={(type) => setCompose(type === "collage" ? "collage-new" : type === "journal" ? "journal-new" : "checkin-new")}
          />
        )}
      </div>

      <BottomNav view={view} setView={setView} onCompose={() => {
        if (view === "feed") setCompose("photo");
        else setCompose("scrapbook-menu");
      }} />

      {compose === "scrapbook-menu" && <ScrapbookComposeMenu
        onClose={() => setCompose(null)}
        onPick={(t) => setCompose(t)} />}
      {compose === "photo" && <ComposePhotoModal onClose={() => setCompose(null)} onSave={addEntry} />}
      {compose === "collage-new" && <CreateCollage onClose={() => setCompose(null)} onSave={(e) => { const full = addEntry(e); setEditingScrapbookEntry(full); }} photoImages={photoImages} />}
      {compose === "journal-new" && <JournalEditor entry={null} onClose={() => setCompose(null)} onSave={(e) => addEntry(e)} photoImages={photoImages} />}
      {compose === "checkin-new" && <CheckInFlow onClose={() => setCompose(null)} onSave={(e) => addEntry(e)} photoImages={photoImages} />}

      {openEntry && (
        <EntryViewer
          entry={openEntry}
          onClose={() => setOpenEntry(null)}
          onDelete={() => deleteEntry(openEntry.id)}
          onEdit={() => { setEditingScrapbookEntry(openEntry); setOpenEntry(null); }}
        />
      )}

      {editingScrapbookEntry && editingScrapbookEntry.type === "collage" && (
        <CollageEditor
          entry={editingScrapbookEntry}
          onClose={() => setEditingScrapbookEntry(null)}
          onUpdate={(patch) => updateEntry(editingScrapbookEntry.id, patch)}
          onDelete={() => deleteEntry(editingScrapbookEntry.id)}
          photoImages={photoImages}
        />
      )}
      {editingScrapbookEntry && editingScrapbookEntry.type === "journal" && (
        <JournalEditor
          entry={editingScrapbookEntry}
          onClose={() => setEditingScrapbookEntry(null)}
          onSave={(patch) => { updateEntry(editingScrapbookEntry.id, patch); setEditingScrapbookEntry(null); }}
          onDelete={() => deleteEntry(editingScrapbookEntry.id)}
          photoImages={photoImages}
        />
      )}
      {editingScrapbookEntry && editingScrapbookEntry.type === "checkin" && (
        <EntryViewer entry={editingScrapbookEntry} onClose={() => setEditingScrapbookEntry(null)} onDelete={() => deleteEntry(editingScrapbookEntry.id)} />
      )}
    </div>
  );
}

