// ---------- Square post — uniform for every entry type ----------
function FeedPost({ entry, index, onOpen }) {
  const tilt = [-1.4, 1.1, -0.7, 1.5, -1.2, 0.8, -1.6][index % 7];
  const cover = getCoverPhoto(entry);

  const typePills = {
    photo: null,
    collage: { label: "collage", color: "#A78BFA", icon: Layers },
    journal: { label: "journal", color: "#FFD166", icon: FileText },
    checkin: { label: "check-in", color: "#60E5FF", icon: ClipboardCheck },
  };
  const pill = typePills[entry.type];
  const PillIcon = pill?.icon;

  const caption = entry.type === "photo" ? entry.caption
    : entry.type === "checkin" ? (entry.carry?.trim() || entry.vibeNotes?.trim() || "a moment of reflection.")
    : entry.caption?.trim() || entry.title?.trim() || (entry.type === "journal" ? (entry.body || "").slice(0, 140) : "untitled");

  return (
    <div onClick={onOpen} className="relative slide-in cursor-pointer group"
      style={{ transform: `rotate(${tilt}deg)`, transition: "transform 0.3s" }}
      onMouseEnter={e => e.currentTarget.style.transform = `rotate(${tilt/2}deg) translateY(-3px) scale(1.01)`}
      onMouseLeave={e => e.currentTarget.style.transform = `rotate(${tilt}deg)`}>
      <div className="absolute -inset-0.5 rounded-[28px] iridescent opacity-60 blur-sm group-hover:opacity-100 transition" />
      <div className="relative rounded-[26px] overflow-hidden glass" style={{boxShadow: "0 20px 60px -20px rgba(255, 110, 199, 0.5)"}}>
        {/* Square cover */}
        <div className="relative" style={{aspectRatio: "1/1"}}>
          {cover.type === "image" ? (
            <img src={cover.src} alt="" className="w-full h-full object-cover" crossOrigin="anonymous" />
          ) : (
            <GeneratedCover entryType={cover.entryType} date={cover.date} />
          )}

          {/* mood (photo posts only) */}
          {entry.type === "photo" && entry.mood && (
            <div className="absolute top-3 right-3 w-10 h-10 rounded-full flex items-center justify-center text-lg glass-light">
              {entry.mood}
            </div>
          )}

          {/* date top-left */}
          <div className="absolute top-3 left-3 px-2.5 py-1 rounded-full text-white"
            style={{background: "rgba(0,0,0,0.5)", backdropFilter: "blur(10px)", fontFamily: "'VT323', monospace", fontSize: "13px", letterSpacing: "0.1em"}}>
            ▸ {entry.date}
          </div>

          {/* type pill — bottom right */}
          {pill && (
            <div className="absolute bottom-3 right-3 px-2.5 py-1 rounded-full flex items-center gap-1.5 text-white"
              style={{
                background: `rgba(0,0,0,0.55)`,
                backdropFilter: "blur(10px)",
                border: `1px solid ${pill.color}80`,
                boxShadow: `0 0 12px ${pill.color}60`,
              }}>
              {PillIcon && <PillIcon className="w-3 h-3" style={{color: pill.color}} />}
              <span style={{fontFamily: "'VT323', monospace", fontSize: "12px", letterSpacing: "0.1em", color: pill.color}}>
                {pill.label}
              </span>
            </div>
          )}
        </div>

        {/* caption */}
        <div className="p-4 pb-5">
          <p className="text-white leading-snug" style={{fontSize: "15px"}}>
            {caption.length > 140 ? caption.slice(0, 140) + "..." : caption}
          </p>
          <div className="flex items-center justify-between mt-3 text-[11px] text-white/50">
            <span style={{fontFamily: "'VT323', monospace", fontSize: "13px"}}>{entry.time}</span>
            <span className="flex items-center gap-1">
              <Heart className="w-3 h-3" fill="currentColor" /> only me
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

