// ============================================================
// PHOTO COMPOSE
// ============================================================
function ComposePhotoModal({ onClose, onSave }) {
  const [image, setImage] = useState("");
  const [caption, setCaption] = useState("");
  const [mood, setMood] = useState("✨");
  const fileInputRef = useRef(null);

  const [uploading, setUploading] = useState(false);
  const handleFile = async (e) => {
    const file = e.target.files?.[0]; if (!file) return;
    setUploading(true);
    try {
      const url = await uploadPhoto(file);
      setImage(url);
    } catch (err) {
      console.error("photo upload failed", err);
      alert("upload failed — try again?");
    } finally {
      setUploading(false);
      e.target.value = "";
    }
  };

  const save = () => {
    if (!image) return;
    onSave({ type: "photo", image, caption: caption || "...", mood, date: todayDate(), time: nowTime() });
  };

  return (
    <div className="fixed inset-0 z-40 flex items-end sm:items-center justify-center backdrop-blur-md fade-in"
      style={{background: "rgba(60, 35, 110, 0.4)"}} onClick={onClose}>
      <div onClick={e => e.stopPropagation()} className="w-full max-w-md p-5 slide-in"
        style={{
          maxHeight: "92vh", overflowY: "auto",
          background: "linear-gradient(160deg, #f7d6ff 0%, #c5b3ff 50%, #ffb4de 100%)",
          borderRadius: "28px 28px 0 0", border: "1px solid rgba(255,255,255,0.15)",
          boxShadow: "0 -20px 60px rgba(255,110,199,0.3)",
        }}>
        <div className="flex items-center justify-between mb-4">
          <h2 className="iridescent-text" style={{fontFamily: "'Pacifico', cursive", fontSize: "28px"}}>new photo ✦</h2>
          <button onClick={onClose} className="w-8 h-8 rounded-full glass-light flex items-center justify-center">
            <X className="w-4 h-4" style={{color: "#3d1d6b"}} />
          </button>
        </div>
        <button onClick={() => fileInputRef.current?.click()}
          className="w-full aspect-square rounded-2xl overflow-hidden flex items-center justify-center mb-4 transition"
          style={{background: image ? "transparent" : "rgba(255,255,255,0.05)", border: image ? "none" : "2px dashed rgba(255,110,199,0.5)"}}>
          {image ? <img src={image} alt="" className="w-full h-full object-cover" crossOrigin="anonymous" /> : (
            <div className="text-center">
              <ImageIcon className="w-10 h-10 mx-auto mb-2 text-pink-300" />
              <p style={{color: "#4a2e7a", fontFamily: "'VT323', monospace", fontSize: "15px", letterSpacing: "0.1em"}}>▸ tap to add photo</p>
            </div>
          )}
        </button>
        <input ref={fileInputRef} type="file" accept="image/*" onChange={handleFile} className="hidden" />
        <textarea value={caption} onChange={e => setCaption(e.target.value)}
          placeholder="what happened? what did you notice?"
          className="w-full p-3 rounded-xl outline-none resize-none mb-3 placeholder-[#7a5aa8]/50"
          style={{color: "#2d1b4e", background: "rgba(255,255,255,0.5)", border: "1px solid rgba(167,139,250,0.35)", fontSize: 15}}
          rows={3} />
        <div className="mb-4">
          <p className="mb-2" style={{color: "#6b4aa8", fontFamily: "'VT323', monospace", fontSize: "13px", letterSpacing: "0.1em", textTransform: "uppercase"}}>▸ mood</p>
          <div className="flex flex-wrap gap-1.5">
            {STICKERS.slice(0, 14).map(s => (
              <button key={s} onClick={() => setMood(s)}
                className="w-9 h-9 rounded-full text-lg flex items-center justify-center transition"
                style={{
                  background: mood === s ? "linear-gradient(110deg, #ff6ec7, #a78bfa)" : "rgba(255,255,255,0.08)",
                  transform: mood === s ? "scale(1.15)" : "scale(1)",
                  boxShadow: mood === s ? "0 4px 12px rgba(255,110,199,0.5)" : "none",
                }}>
                {s}
              </button>
            ))}
          </div>
        </div>
        <button onClick={save} disabled={!image}
          className="w-full py-3 rounded-xl text-white transition disabled:opacity-30 iridescent"
          style={{boxShadow: "0 4px 20px rgba(255,110,199,0.5)"}}>
          save to feed ✦
        </button>
      </div>
    </div>
  );
}

// ============================================================
// COVER PHOTO PICKER — shared UI component
// ============================================================
function CoverPicker({ coverPhoto, setCoverPhoto, availableImages, entryType, date }) {
  return (
    <div className="mb-4">
      <p className="mb-2" style={{color: "#6b4aa8", fontFamily: "'VT323', monospace", fontSize: "13px", letterSpacing: "0.1em", textTransform: "uppercase"}}>
        ▸ cover photo (shown on feed)
      </p>
      <div className="flex gap-2 overflow-x-auto pb-1" style={{scrollbarWidth: "none"}}>
        {/* Auto/none option — generated cover */}
        <button onClick={() => setCoverPhoto(null)}
          className="flex-shrink-0 w-20 h-20 rounded-xl overflow-hidden relative transition"
          style={{
            border: coverPhoto === null ? "2px solid #ff6ec7" : "1px solid rgba(255,255,255,0.2)",
            boxShadow: coverPhoto === null ? "0 0 12px rgba(255,110,199,0.5)" : "none",
          }}>
          <GeneratedCover entryType={entryType} date={date} />
          <div className="absolute bottom-0 inset-x-0 bg-black/70 text-white text-[9px] text-center py-0.5"
            style={{fontFamily: "'VT323', monospace", letterSpacing: "0.1em"}}>
            auto
          </div>
        </button>
        {availableImages.map((img, i) => {
          const selected = coverPhoto === img;
          return (
            <button key={i} onClick={() => setCoverPhoto(img)}
              className="flex-shrink-0 w-20 h-20 rounded-xl overflow-hidden transition"
              style={{
                border: selected ? "2px solid #ff6ec7" : "1px solid rgba(255,255,255,0.2)",
                boxShadow: selected ? "0 0 12px rgba(255,110,199,0.5)" : "none",
              }}>
              <img src={img} alt="" className="w-full h-full object-cover" crossOrigin="anonymous" />
            </button>
          );
        })}
      </div>
      {availableImages.length === 0 && (
        <p className="text-xs italic mt-2" style={{color: "#8a6aa8"}}>add photos inside and they'll show up here</p>
      )}
    </div>
  );
}

